const { useState } = React;

function App() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [subscribe, setSubscribe] = useState(false);
  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);

  function validate() {
    const newErrors = {};
    if (!name.trim()) newErrors.name = "Name is required.";
    if (!email.trim()) newErrors.email = "Email is required.";
    if (!password.trim()) newErrors.password = "Password is required.";
    return newErrors;
  }

  function handleSubmit(e) {
    e.preventDefault();
    const validationErrors = validate();
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length === 0) {
      setSubmitted(true);
    }
  }

  function handleCancel() {
    setName("");
    setEmail("");
    setPassword("");
    setSubscribe(false);
    setErrors({});
    setSubmitted(false);
  }

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
            Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
          background: #fff;
          color: #222;
        }
        .container {
          display: flex;
          max-width: 900px;
          margin: 40px auto;
          gap: 40px;
          padding: 0 20px;
          align-items: flex-start;
        }
        main {
          flex: 1 1 0;
        }
        h1 {
          font-weight: 600;
          font-size: 2rem;
          margin-bottom: 8px;
          border-bottom: 2px solid #444;
          padding-bottom: 4px;
          max-width: max-content;
        }
        p.intro {
          margin-top: 0;
          margin-bottom: 24px;
          color: #555;
          line-height: 1.4;
        }
        form {
          display: flex;
          flex-direction: column;
          gap: 16px;
          max-width: 320px;
        }
        label {
          display: flex;
          flex-direction: column;
          font-size: 0.9rem;
          color: #333;
        }
        input[type="text"],
        input[type="email"],
        input[type="password"] {
          margin-top: 6px;
          padding: 10px 12px;
          font-size: 1rem;
          border: 1.8px solid #999;
          border-radius: 6px;
          font-family: inherit;
          transition: border-color 0.2s ease;
        }
        input[type="text"]:focus,
        input[type="email"]:focus,
        input[type="password"]:focus {
          border-color: #0078d7;
          outline: none;
        }
        .checkbox-label {
          font-weight: 400;
          font-size: 0.9rem;
          display: flex;
          align-items: center;
          gap: 8px;
          user-select: none;
          cursor: pointer;
        }
        input[type="checkbox"] {
          width: 18px;
          height: 18px;
          cursor: pointer;
        }
        .buttons {
          display: flex;
          gap: 16px;
          margin-top: 8px;
        }
        button {
          font-size: 1rem;
          padding: 10px 24px;
          border-radius: 20px;
          border: 2px solid #444;
          cursor: pointer;
          font-weight: 600;
          transition: background-color 0.2s ease, color 0.2s ease;
          user-select: none;
        }
        button:focus {
          outline: 3px solid #0078d7;
          outline-offset: 2px;
        }
        button.sign-up {
          background-color: #444;
          color: white;
          border-color: #444;
        }
        button.sign-up:hover {
          background-color: #222;
          border-color: #222;
        }
        button.cancel {
          background-color: transparent;
          color: #444;
          border-color: #444;
          border-radius: 6px;
          padding-left: 20px;
          padding-right: 20px;
        }
        button.cancel:hover {
          background-color: #eee;
        }
        .error {
          color: #b00020;
          font-size: 0.85rem;
          margin-top: 4px;
          font-weight: 600;
        }
        .welcome-message {
          font-size: 1.4rem;
          font-weight: 600;
          color: #0078d7;
          margin-top: 24px;
        }
        aside {
          flex: 1 1 0;
          max-width: 400px;
          border-radius: 12px;
          overflow: hidden;
          box-shadow: 0 4px 12px rgb(0 0 0 / 0.15);
        }
        aside img {
          width: 100%;
          height: auto;
          display: block;
          object-fit: cover;
          aspect-ratio: 1 / 1;
        }
      `}</style>
      <div className="container">
        <main>
          <h1>Join the club</h1>
          <p className="intro">Become a member to enjoy exclusive benefits and updates.</p>
          {!submitted ? (
            <form onSubmit={handleSubmit} noValidate>
              <label htmlFor="name">
                Name
                <input
                  id="name"
                  type="text"
                  value={name}
                  onChange={e => setName(e.target.value)}
                  aria-describedby={errors.name ? "name-error" : undefined}
                  aria-invalid={errors.name ? "true" : "false"}
                />
                {errors.name && (
                  <span role="alert" id="name-error" className="error">
                    {errors.name}
                  </span>
                )}
              </label>

              <label className="checkbox-label" htmlFor="subscribe">
                <input
                  id="subscribe"
                  type="checkbox"
                  checked={subscribe}
                  onChange={e => setSubscribe(e.target.checked)}
                />
                Subscribe to newsletter
              </label>

              <label htmlFor="email">
                Email
                <input
                  id="email"
                  type="email"
                  value={email}
                  onChange={e => setEmail(e.target.value)}
                  aria-describedby={errors.email ? "email-error" : undefined}
                  aria-invalid={errors.email ? "true" : "false"}
                />
                {errors.email && (
                  <span role="alert" id="email-error" className="error">
                    {errors.email}
                  </span>
                )}
              </label>

              <label htmlFor="password">
                Password
                <input
                  id="password"
                  type="password"
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  aria-describedby={errors.password ? "password-error" : undefined}
                  aria-invalid={errors.password ? "true" : "false"}
                />
                {errors.password && (
                  <span role="alert" id="password-error" className="error">
                    {errors.password}
                  </span>
                )}
              </label>

              <div className="buttons">
                <button type="submit" className="sign-up">
                  Sign up
                </button>
                <button type="button" className="cancel" onClick={handleCancel}>
                  Cancel
                </button>
              </div>
            </form>
          ) : (
            <p className="welcome-message" tabIndex={-1} aria-live="polite">
              Welcome aboard.
            </p>
          )}
        </main>
        <aside>
          <img src="/runtime/photos/person.jpg" alt="Membership club" />
        </aside>
      </div>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

